"""
Boolean Degree One Functions on the q-Grassmann Scheme J_q(n,2)
===============================================================

Self-contained numerical demonstration of the elementary combinatorial
framework formalized in the accompanying Lean development.

We model J_q(n,2) as a finite linear space: a set of points P, a set of lines L,
and an incidence map sending each line to its set of points such that

    * every line has exactly q+1 points        (uniformity), and
    * any two distinct points lie on a unique line (unique line).

A function f : L -> R is
    * degree <= 1  if  f(l) = c + sum_{p in l} w(p)  for some constant c and
                       point-weight w : P -> R;
    * Boolean      if  f(l) in {0, 1} for every line l;
    * Boolean degree one if it is both.

This script builds the Fano plane PG(2,2) = J_2(3,2) and a slice of PG(3,3),
constructs the trivial Boolean degree one functions (constants, point-pencils,
complements), verifies the main theorems numerically, and demonstrates the
"sum of two pencils" obstruction.

Run:  python demo.py
"""

from __future__ import annotations

from itertools import combinations
from typing import Callable, Dict, FrozenSet, List, Tuple


# ---------------------------------------------------------------------------
# Finite linear space data structure
# ---------------------------------------------------------------------------

class LinearSpace:
    """A finite linear space: points, lines, and an incidence relation."""

    def __init__(self, points: List[int], lines: List[FrozenSet[int]]) -> None:
        self.points: List[int] = list(points)
        self.lines: List[FrozenSet[int]] = list(lines)

    def line_size(self, line: FrozenSet[int]) -> int:
        return len(line)

    def is_uniform(self) -> Tuple[bool, int]:
        """Return (uniform?, common q+1) where common is the shared line size."""
        sizes = {self.line_size(l) for l in self.lines}
        if len(sizes) == 1:
            return True, next(iter(sizes))
        return False, -1

    def unique_line_axiom(self) -> bool:
        """Every pair of distinct points lies on exactly one common line."""
        for p, p2 in combinations(self.points, 2):
            count = sum(1 for l in self.lines if p in l and p2 in l)
            if count != 1:
                return False
        return True

    def through(self) -> bool:
        return all(any(p in l for l in self.lines) for p in self.points)

    def avoid(self) -> bool:
        return all(any(p not in l for l in self.lines) for p in self.points)

    def separating(self) -> bool:
        for p in self.points:
            for p2 in self.points:
                if p != p2 and not any(p in l and p2 not in l for l in self.lines):
                    return False
        return True


# ---------------------------------------------------------------------------
# Functions on lines: degree-one description and Booleanity
# ---------------------------------------------------------------------------

def deg_one_function(
    space: LinearSpace, c: float, w: Dict[int, float]
) -> Callable[[FrozenSet[int]], float]:
    """Return f(l) = c + sum_{p in l} w(p) as a callable on lines."""
    def f(line: FrozenSet[int]) -> float:
        return c + sum(w.get(p, 0.0) for p in line)
    return f


def is_boolean(space: LinearSpace, f: Callable[[FrozenSet[int]], float]) -> bool:
    return all(abs(f(l)) < 1e-9 or abs(f(l) - 1.0) < 1e-9 for l in space.lines)


def values(space: LinearSpace, f: Callable[[FrozenSet[int]], float]) -> Tuple[float, ...]:
    return tuple(round(f(l), 9) for l in space.lines)


# ---------------------------------------------------------------------------
# The trivial Boolean degree one functions
# ---------------------------------------------------------------------------

def const_function(space: LinearSpace, value: float) -> Callable[[FrozenSet[int]], float]:
    """Constant function: c = value, w = 0  (Theorems const_zero_BDO/const_one_BDO)."""
    return deg_one_function(space, value, {})


def pencil_indicator(space: LinearSpace, p: int) -> Callable[[FrozenSet[int]], float]:
    """ind(p): 1 on lines through p, else 0.  c = 0, Kronecker weight (pencil_BDO)."""
    return deg_one_function(space, 0.0, {p: 1.0})


def complement(
    space: LinearSpace, f: Callable[[FrozenSet[int]], float]
) -> Callable[[FrozenSet[int]], float]:
    """1 - f, again Boolean degree one (compl_BDO)."""
    def g(line: FrozenSet[int]) -> float:
        return 1.0 - f(line)
    return g


def sum_of_two_pencils(
    space: LinearSpace, p: int, p2: int
) -> Callable[[FrozenSet[int]], float]:
    """ind(p) + ind(p'): degree one but NOT Boolean (two_pencils_not_boolean)."""
    return deg_one_function(space, 0.0, {p: 1.0, p2: 1.0})


# ---------------------------------------------------------------------------
# Concrete spaces
# ---------------------------------------------------------------------------

def fano_plane() -> LinearSpace:
    """PG(2,2) = J_2(3,2): 7 points, 7 lines, 3 points per line."""
    points = list(range(7))
    lines = [
        frozenset({0, 1, 2}),
        frozenset({0, 3, 4}),
        frozenset({0, 5, 6}),
        frozenset({1, 3, 5}),
        frozenset({1, 4, 6}),
        frozenset({2, 3, 6}),
        frozenset({2, 4, 5}),
    ]
    return LinearSpace(points, lines)


def projective_plane_pg2q(q: int) -> LinearSpace:
    """PG(2,q) for prime q: q^2+q+1 points and lines, q+1 points per line.

    Points are 1-dim subspaces of F_q^3, represented by normalized homogeneous
    coordinates.  Lines are 2-dim subspaces, each the set of points orthogonal
    to a normal vector.
    """
    def normalize(v: Tuple[int, int, int]) -> Tuple[int, int, int]:
        for x in v:
            if x % q != 0:
                inv = pow(x % q, q - 2, q)  # modular inverse (q prime)
                return tuple((c * inv) % q for c in v)  # type: ignore[return-value]
        return v

    reps = set()
    for a in range(q):
        for b in range(q):
            for c in range(q):
                if (a, b, c) != (0, 0, 0):
                    reps.add(normalize((a, b, c)))
    point_reps = sorted(reps)
    point_index = {r: i for i, r in enumerate(point_reps)}

    def dot(u: Tuple[int, int, int], v: Tuple[int, int, int]) -> int:
        return sum(x * y for x, y in zip(u, v)) % q

    lines = set()
    for normal in point_reps:  # each normalized vector gives one line
        line = frozenset(
            point_index[r] for r in point_reps if dot(normal, r) == 0
        )
        if len(line) > 0:
            lines.add(line)
    return LinearSpace(list(range(len(point_reps))), list(lines))


# ---------------------------------------------------------------------------
# Demonstrations
# ---------------------------------------------------------------------------

def demo_axioms(space: LinearSpace, name: str) -> None:
    uniform, qp1 = space.is_uniform()
    print(f"--- {name} ---")
    print(f"  |P| = {len(space.points)}, |L| = {len(space.lines)}")
    print(f"  uniform line size (q+1): {uniform}  ->  q+1 = {qp1}, so q = {qp1 - 1}")
    print(f"  unique-line axiom: {space.unique_line_axiom()}")
    print(f"  through / avoid / separating: "
          f"{space.through()} / {space.avoid()} / {space.separating()}")


def demo_trivial_solutions(space: LinearSpace) -> None:
    print("  Trivial Boolean degree one functions:")
    f0, f1 = const_function(space, 0.0), const_function(space, 1.0)
    print(f"    const 0  Boolean? {is_boolean(space, f0)}   values={values(space, f0)}")
    print(f"    const 1  Boolean? {is_boolean(space, f1)}   values={values(space, f1)}")
    p = space.points[0]
    pen = pencil_indicator(space, p)
    print(f"    pencil(p={p})  Boolean? {is_boolean(space, pen)}   "
          f"values={values(space, pen)}")
    comp = complement(space, pen)
    print(f"    1 - pencil(p={p})  Boolean? {is_boolean(space, comp)}   "
          f"values={values(space, comp)}")


def demo_counting(space: LinearSpace) -> None:
    """Verify the >= |P| + 2 lower bound (exists_many_BDO)."""
    seen = set()
    seen.add(values(space, const_function(space, 0.0)))
    seen.add(values(space, const_function(space, 1.0)))
    for p in space.points:
        seen.add(values(space, pencil_indicator(space, p)))
    distinct = len(seen)
    print(f"  distinct {{const 0, const 1}} U {{pencils}}: {distinct}  "
          f"(lower bound |P|+2 = {len(space.points) + 2})  "
          f"-> match: {distinct == len(space.points) + 2}")


def demo_const_weight_is_constant(space: LinearSpace) -> None:
    """A constant weight a yields a constant function (const_weight_is_constant)."""
    a, c = 0.37, 1.5
    f = deg_one_function(space, c, {p: a for p in space.points})
    vals = values(space, f)
    _, qp1 = space.is_uniform()
    print(f"  constant weight a={a}, c={c}: f is constant? "
          f"{len(set(vals)) == 1}  (= c + (q+1)*a = {round(c + qp1 * a, 9)})")


def demo_obstruction(space: LinearSpace) -> None:
    """Sum of two pencils is degree one but not Boolean (two_pencils_not_boolean)."""
    p, p2 = space.points[0], space.points[1]
    g = sum_of_two_pencils(space, p, p2)
    # find the unique common line
    common = [set(l) for l in space.lines if p in l and p2 in l]
    print(f"  g = pencil({p}) + pencil({p2}): Boolean? {is_boolean(space, g)}")
    if common:
        line = frozenset(common[0])
        print(f"    unique line through {p},{p2} = {sorted(line)}, "
              f"g = {g(line)}  (= 2, not in {{0,1}})")


def main() -> None:
    print("=" * 70)
    print("Boolean Degree One Functions on J_q(n,2) -- numerical demonstration")
    print("=" * 70)

    fano = fano_plane()
    demo_axioms(fano, "Fano plane PG(2,2) = J_2(3,2)")
    demo_trivial_solutions(fano)
    demo_counting(fano)
    demo_const_weight_is_constant(fano)
    demo_obstruction(fano)
    print()

    pg23 = projective_plane_pg2q(3)
    demo_axioms(pg23, "Projective plane PG(2,3) (q = 3, q+1 = 4)")
    demo_trivial_solutions(pg23)
    demo_counting(pg23)
    demo_const_weight_is_constant(pg23)
    demo_obstruction(pg23)
    print()

    pg25 = projective_plane_pg2q(5)
    demo_axioms(pg25, "Projective plane PG(2,5) (q = 5, q+1 = 6)")
    demo_counting(pg25)
    demo_obstruction(pg25)

    print("\nAll demonstrations completed.")


if __name__ == "__main__":
    main()
